// Package version defines the semantic version of the operator generator.
package version

import "strings"

// Current is the semantic version of the generator. Every generated file names it in its header.
const Current = "v0.1.0-beta.3"

// Tool is the name of the generator in the header of every generated file.
const Tool = "coralogix-operator-codegen"

// GoHeader is the exact first line of every generated Go file.
const GoHeader = "// Code generated by " + Tool + " " + Current + ". DO NOT EDIT."

// YAMLHeader is the exact first line of every generated YAML file.
const YAMLHeader = "# Code generated by " + Tool + " " + Current + ". DO NOT EDIT."

// Owned reports whether line is the first line of a file that a version of the generator wrote.
// The generator overwrites or removes only such a file.
func Owned(line string) bool {
	for _, prefix := range []string{"// ", "# "} {
		rest, ok := strings.CutPrefix(line, prefix+"Code generated by "+Tool+" v")
		if !ok {
			continue
		}
		semver, ok := strings.CutSuffix(rest, ". DO NOT EDIT.")
		return ok && semver != "" && !strings.ContainsAny(semver, " \t")
	}
	return false
}
